import sys

def main():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    n = int(data[0])
    l = [int(x) for x in data[1:n+1]]

    total = sum(l)
    if total % 2 != 0:
        print('N')
        return

    half = total // 2

    # Prefix sums
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i + 1] = pref[i] + l[i]

    pairs = 0
    j = 0
    for i in range(n):
        if pref[i] >= half:
            break
        while j < n and pref[j] - pref[i] < half:
            j += 1
        if j < n and pref[j] - pref[i] == half:
            pairs += 1
            if pairs >= 2:
                print('S')
                return

    print('N')

if __name__ == '__main__':
    main()
